const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const text = typeof body.message === 'string' ? body.message.trim() : (typeof body.text === 'string' ? body.text.trim() : '');
const name = typeof body.name === 'string' ? body.name.trim() : '';
const phone = typeof body.phone === 'string' ? body.phone.trim() : '';
const errors = [];
if (!text) errors.push('message is required');
if (!phone) errors.push('phone is required');
if (text.length > 2000) errors.push('message must be at most 2000 characters');
if (errors.length) return [{ json: { valid: false, errors } }];

const lower = text.toLowerCase();
let service = 'General Consultation';
if (lower.includes('dermat') || lower.includes('skin')) service = 'Dermatology';
else if (lower.includes('dental') || lower.includes('dentist')) service = 'Dental';
else if (lower.includes('pediatric') || lower.includes('child')) service = 'Pediatrics';

const bookingWords = ['appointment', 'book', 'slot', 'available', 'availability', 'schedule', 'visit'];
const intent = bookingWords.some(k => lower.includes(k)) ? 'Appointment Booking' : 'General Enquiry';

let preferredTime = null;
const timeMatch = text.match(/\b(1[0-2]|0?[1-9])(?::([0-5]\d))?\s*(am|pm)\b/i);
if (timeMatch) preferredTime = `${timeMatch[1]}${timeMatch[2] ? ':' + timeMatch[2] : ':00'} ${timeMatch[3].toUpperCase()}`;
let preferredDate = 'Needs confirmation';
if (lower.includes('tomorrow')) preferredDate = 'Tomorrow';
else if (lower.includes('today')) preferredDate = 'Today';

return [{ json: {
  valid: true,
  lead_id: `LZ-${$execution.id}`,
  lead_name: name || 'Unknown',
  phone, message: text,
  source: typeof body.source === 'string' ? body.source : 'WhatsApp',
  intent, service,
  preferred_date: preferredDate,
  preferred_time: preferredTime ?? 'Needs confirmation',
  received_at: new Date().toISOString()
} }];

const lead = $json;
let score = 20;

if (lead.intent === 'Appointment Booking') score += 25;
if (lead.service !== 'General Consultation') score += 10;
if (lead.preferred_date !== 'Needs confirmation') score += 10;
if (lead.preferred_time !== 'Needs confirmation') score += 10;
if (/^\+?[1-9]\d{9,14}$/.test(lead.phone.replace(/[\s-]/g, ''))) score += 5;

score = Math.min(score, 100);

let qualification = 'Cold';
if (score >= 80) qualification = 'Hot';
else if (score >= 60) qualification = 'Warm';

let next_action = 'Send information and request preferred appointment details';
if (qualification === 'Hot') next_action = 'Check calendar availability and offer booking slot';
else if (qualification === 'Warm') next_action = 'Ask one qualification question and offer available slots';

return [{
  json: {
    ...lead,
    lead_score: score,
    qualification,
    next_action,
    demo_note: 'Demo workflow - rule-based scoring, no external systems called'
  }
}];

const x = $json;
return [{
  json: {
    ...x,
    calendar_action: 'CHECK_AVAILABILITY',
    crm_stage: 'Qualified - Booking Ready',
    owner_alert: `HOT LEAD: ${x.lead_name} wants ${x.service} on ${x.preferred_date} at ${x.preferred_time}`,
    whatsapp_reply: `Hi ${x.lead_name}, thanks for contacting us. I have your ${x.service} appointment request for ${x.preferred_date} at ${x.preferred_time}. I’m checking availability now and will confirm the closest available slot.`
  }
}];

const x = $json;
return [{
  json: {
    ...x,
    calendar_action: 'ASK_FOR_DETAILS',
    crm_stage: 'Qualified - Needs Details',
    owner_alert: `WARM LEAD: ${x.lead_name} is interested in ${x.service}`,
    whatsapp_reply: `Hi ${x.lead_name}, I can help with your ${x.service} booking. What date and time would work best for you?`
  }
}];

const x = $json;
return [{
  json: {
    ...x,
    calendar_action: 'NO_BOOKING_YET',
    crm_stage: 'New Lead - Nurture',
    owner_alert: `NEW LEAD: ${x.lead_name} needs follow-up`,
    whatsapp_reply: `Hi ${x.lead_name}, thanks for reaching out. Please tell us which service you need and your preferred appointment date/time, and we’ll help you with the next available slot.`
  }
}];
